/* ---- Side Panel Translator Plus: bridge between page overlays and the side panel ---- */
(function () {
  var PENDING_KEY = 'plusPendingText';

  try {
    importScripts('plus/bootstrap.js');
  } catch (e) {}

  function seedConfig() {
    var seed = self.PLUS_BOOTSTRAP;
    if (!seed) return;
    try {
      chrome.storage.local.get(
        ['translateServiceConfig', 'translateServiceStatus', 'generalForm'],
        function (res) {
          if (chrome.runtime.lastError || !res) return;
          var patch = {};

          var storedConfig = res.translateServiceConfig || {};
          var seedConfig = seed.translateServiceConfig || {};
          var mergedConfig = {};
          Object.keys(storedConfig).forEach(function (k) {
            mergedConfig[k] = storedConfig[k];
          });
          var configChanged = false;
          Object.keys(seedConfig).forEach(function (k) {
            if (!mergedConfig[k]) {
              mergedConfig[k] = seedConfig[k];
              configChanged = true;
            }
          });
          if (configChanged) patch.translateServiceConfig = mergedConfig;

          var storedStatus = res.translateServiceStatus || {};
          var seedStatus = seed.translateServiceStatus || {};
          var mergedStatus = {};
          var statusChanged = false;
          Object.keys(storedStatus).forEach(function (k) {
            mergedStatus[k] = storedStatus[k];
          });
          Object.keys(seedStatus).forEach(function (k) {
            if (!(k in mergedStatus) && seedStatus[k]) {
              mergedStatus[k] = true;
              statusChanged = true;
            }
          });
          if (statusChanged) patch.translateServiceStatus = mergedStatus;

          if (!res.generalForm && seed.generalForm) patch.generalForm = seed.generalForm;
          if (!Object.keys(patch).length) return;
          chrome.storage.local.set(patch);
        }
      );
    } catch (e) {}
  }

  seedConfig();
  setTimeout(seedConfig, 600);
  setTimeout(seedConfig, 1500);
  setTimeout(seedConfig, 3500);

  function broadcast(text) {
    if (!text) return;
    try {
      chrome.runtime.sendMessage({ name: 'plusTranslateText', data: { text: text } }, function () {
        void chrome.runtime.lastError;
      });
    } catch (e) {}
  }

  function remember(text) {
    if (!text) return;
    try {
      chrome.storage.local.set({ [PENDING_KEY]: { text: text, at: Date.now() } });
    } catch (e) {}
  }

  function deliver(text, delay) {
    if (!text) return;
    remember(text);
    setTimeout(function () {
      broadcast(text);
    }, delay || 0);
  }

  try {
    chrome.runtime.onInstalled.addListener(function () {
      try {
        chrome.contextMenus.removeAll(function () {
          chrome.contextMenus.create({
            id: 'plus-translate-selection',
            title: '在侧边栏翻译“%s”',
            contexts: ['selection']
          });
          chrome.contextMenus.create({
            id: 'plus-open-panel',
            title: '打开翻译侧边栏',
            contexts: ['page']
          });
        });
      } catch (e) {}
    });

    chrome.contextMenus.onClicked.addListener(function (info, tab) {
      var text = info.selectionText || '';
      if (info.menuItemId === 'plus-translate-selection' && text) {
        remember(text);
      }
      try {
        var target = tab && tab.id ? { tabId: tab.id } : tab && tab.windowId ? { windowId: tab.windowId } : null;
        if (target && chrome.sidePanel && typeof chrome.sidePanel.open === 'function') {
          chrome.sidePanel.open(target).then(function () {
            if (text) {
              deliver(text, 300);
              deliver(text, 1500);
            }
          }).catch(function () {});
        }
      } catch (e) {}
    });
  } catch (e) {}

  try {
    chrome.runtime.onMessage.addListener(function (msg, sender, sendResponse) {
      if (!msg) return;

      if (msg.name === 'plusTakePending') {
        chrome.storage.local.get(PENDING_KEY, function (res) {
          var item = res && res[PENDING_KEY];
          if (item && Date.now() - item.at < 120000) {
            chrome.storage.local.remove(PENDING_KEY);
            sendResponse({ text: item.text });
          } else {
            sendResponse(null);
          }
        });
        return true;
      }

      if (msg.name !== 'plusOpenPanel') return;
      var text = (msg.data && msg.data.text) || '';
      var tab = sender && sender.tab;
      var requested = false;

      if (chrome.sidePanel && typeof chrome.sidePanel.open === 'function' && tab) {
        try {
          var target = tab.id ? { tabId: tab.id } : tab.windowId ? { windowId: tab.windowId } : null;
          if (target) {
            requested = true;
            var p = chrome.sidePanel.open(target);
            if (p && typeof p.then === 'function') {
              p.then(function () {
                deliver(text, 250);
                deliver(text, 1200);
              }).catch(function () {
                deliver(text, 0);
              });
            } else {
              deliver(text, 250);
            }
          }
        } catch (e) {
          requested = false;
        }
      }

      if (!requested) {
        remember(text);
      } else {
        remember(text);
      }
      sendResponse({ ok: true, requested: requested });
      return false;
    });
  } catch (e) {}
})();
